UPDATE job_execution SET status=#{status}, message=#{message}, result_json=CAST(#{resultJson} AS JSON),
    error_type=#{errorType}, error_message=#{errorMessage}, finished_at=#{finishedAt}, duration_millis=#{durationMillis}
WHERE id=#{id}

UPDATE job_execution SET status=#{status}, message=#{message}, result_json=CAST(#{resultJson} AS JSON),
    error_type=#{errorType}, error_message=#{errorMessage}, finished_at=#{finishedAt}, duration_millis=#{durationMillis}
WHERE id=#{id} AND status=#{runningStatus}

UPDATE job_execution SET status=#{cancelledStatus}, message=#{message}, result_json=CAST('{}' AS JSON),
    error_type=#{errorType}, error_message=NULL, finished_at=#{finishedAt}, duration_millis=#{durationMillis}
WHERE id=#{id} AND status=#{runningStatus}

mapper.select:
SELECT e.status AS status, COUNT(*) AS total FROM job_execution e
e.started_at >= #{startTime} AND e.started_at < #{endTime}
GROUP BY e.status

SELECT DATE(e.started_at) AS bucket_date, e.status AS status, COUNT(*) AS total FROM job_execution e
e.started_at >= #{startTime} AND e.started_at < #{endTime}
GROUP BY DATE(e.started_at), e.status ORDER BY bucket_date ASC, status ASC

SELECT e.* FROM job_execution e

    e.status IN #{status}


ORDER BY e.started_at DESC, e.id DESC LIMIT #{limit}
